-- Walkies: shelters, dogs and thank-you notes. Safe to run again.
-- Sample rows are flagged is_demo = true and shown as "sample" in the app until real shelters are added.
-- Each statement is on one line because the SQL tool used to apply it stalls on multi-line function bodies.

create table if not exists public.shelters (id uuid primary key default gen_random_uuid(), name text not null, city text, state text, blurb text, is_demo boolean not null default false, created_at timestamptz not null default now()); create table if not exists public.dogs (id uuid primary key default gen_random_uuid(), shelter_id uuid not null references public.shelters(id) on delete cascade, name text not null, age text, breed text, story text, coat text not null default '#B9692F', ear text not null default '#8A4A1E', photo_url text, goal_bowls int not null default 40 check (goal_bowls > 0), is_demo boolean not null default false, active boolean not null default true, created_at timestamptz not null default now()); create table if not exists public.dog_notes (id uuid primary key default gen_random_uuid(), dog_id uuid not null references public.dogs(id) on delete cascade, body text not null check (char_length(body) between 1 and 400), is_demo boolean not null default false, created_at timestamptz not null default now()); alter table public.shelters enable row level security; alter table public.dogs enable row level security; alter table public.dog_notes enable row level security; drop policy if exists shelters_read on public.shelters; create policy shelters_read on public.shelters for select to authenticated using (true); drop policy if exists dogs_read on public.dogs; create policy dogs_read on public.dogs for select to authenticated using (active); drop policy if exists dog_notes_read on public.dog_notes; create policy dog_notes_read on public.dog_notes for select to authenticated using (true); alter table public.profiles add column if not exists dog_id uuid references public.dogs(id) on delete set null; grant update (dog_id) on public.profiles to authenticated;

create or replace function public.dog_totals() returns table (dog_id uuid, walkers int, bowls int) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select p.dog_id, coalesce(sum(s.steps), 0)::bigint as t from public.profiles p left join public.step_days s on s.user_id = p.user_id and s.day between (select starts_on from c) and (select ends_on from c) group by p.user_id, p.dog_id) select ut.dog_id, count(*)::int, coalesce(sum(public.milestone_count(ut.t)), 0)::int from ut group by ut.dog_id $fn$; revoke execute on function public.dog_totals() from public, anon; grant execute on function public.dog_totals() to authenticated;

with s as (insert into public.shelters (name, city, state, blurb, is_demo) select 'Sample Rescue (demo)', 'Sydney', 'NSW', 'A sample shelter so you can see how dog profiles will look. Real shelter partners are coming soon.', true where not exists (select 1 from public.shelters where is_demo) returning id), d as (insert into public.dogs (shelter_id, name, age, breed, story, coat, ear, goal_bowls, is_demo) select s.id, v.name, v.age, v.breed, v.story, v.coat, v.ear, v.goal, true from s, (values ('Biscuit', '3 years', 'Kelpie cross', 'Biscuit loves tennis balls and long walks. He is a bit shy with new people at first, then never leaves your side. (Sample dog.)', '#C98B4B', '#8A5A2B', 40), ('Mabel', '6 years', 'Staffy cross', 'Mabel is a gentle senior who loves a warm blanket and a slow sniff around the yard. (Sample dog.)', '#E3C9A0', '#B58A52', 40), ('Rocky', '1 year', 'Border collie mix', 'Rocky is full of beans and needs a lot of walking. He is learning to sit and wants a family who loves the outdoors. (Sample dog.)', '#2f2d3a', '#14131a', 40), ('Pip', '9 months', 'Terrier cross', 'Pip is small, scruffy and fearless. He loves squeaky toys and hates baths. (Sample dog.)', '#B9B2A5', '#7C766B', 40)) as v(name, age, breed, story, coat, ear, goal) returning id, name) insert into public.dog_notes (dog_id, body, is_demo) select d.id, case d.name when 'Biscuit' then 'Thank you for every step! This is what a thank-you note from the shelter will look like. (Sample note.)' else 'Walk by walk, you are filling my bowl. This is a sample note from the shelter team.' end, true from d where d.name in ('Biscuit', 'Mabel');

-- Switching dogs keeps what the old dog already earned this month. When a walker changes dog, their bowls so far (minus any already banked)
-- are saved against the old dog in dog_bank; the new dog only gets bowls earned after the switch.
create table if not exists public.dog_bank (user_id uuid not null references auth.users(id) on delete cascade, dog_id uuid not null references public.dogs(id) on delete cascade, period date not null, bowls int not null default 0, primary key (user_id, dog_id, period)); alter table public.dog_bank enable row level security; create or replace function public.bank_dog_bowls() returns trigger language plpgsql security definer set search_path = public as $fn$ declare c record; t bigint; b int; banked int; begin if old.dog_id is not null and new.dog_id is distinct from old.dog_id then select starts_on, ends_on into c from public.challenge limit 1; select coalesce(sum(s.steps), 0) into t from public.step_days s where s.user_id = new.user_id and s.day between c.starts_on and c.ends_on; select coalesce(sum(k.bowls), 0) into banked from public.dog_bank k where k.user_id = new.user_id and k.period = c.starts_on; b := public.milestone_count(t) - banked; if b > 0 then insert into public.dog_bank (user_id, dog_id, period, bowls) values (new.user_id, old.dog_id, c.starts_on, b) on conflict (user_id, dog_id, period) do update set bowls = public.dog_bank.bowls + excluded.bowls; end if; end if; return new; end $fn$; revoke execute on function public.bank_dog_bowls() from public, anon, authenticated; create or replace trigger bank_dog before update of dog_id on public.profiles for each row execute function public.bank_dog_bowls();
create or replace function public.dog_totals() returns table (dog_id uuid, walkers int, bowls int) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select p.user_id, p.dog_id, coalesce(sum(s.steps), 0)::bigint as t from public.profiles p left join public.step_days s on s.user_id = p.user_id and s.day between (select starts_on from c) and (select ends_on from c) group by p.user_id, p.dog_id), parts as (select u.user_id, u.dog_id, greatest(public.milestone_count(u.t) - coalesce((select sum(k.bowls) from public.dog_bank k where k.user_id = u.user_id and k.period = (select starts_on from c)), 0), 0)::int as b from ut u union all select k.user_id, k.dog_id, k.bowls from public.dog_bank k where k.period = (select starts_on from c)) select parts.dog_id, count(distinct parts.user_id)::int, coalesce(sum(parts.b), 0)::int from parts group by parts.dog_id $fn$;

-- Each walker sees only their own bowls for each dog, so there is no shared goal for a dog to run out of.
create or replace function public.my_dog_bowls() returns table (dog_id uuid, bowls int) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), me as (select p.dog_id, coalesce((select sum(s.steps) from public.step_days s where s.user_id = p.user_id and s.day between (select starts_on from c) and (select ends_on from c)), 0)::bigint as t from public.profiles p where p.user_id = auth.uid()), banked as (select k.dog_id, k.bowls from public.dog_bank k where k.user_id = auth.uid() and k.period = (select starts_on from c)), parts as (select m.dog_id, greatest(public.milestone_count(m.t) - coalesce((select sum(b.bowls) from banked b), 0), 0)::int as bowls from me m union all select b.dog_id, b.bowls from banked b) select parts.dog_id, sum(parts.bowls)::int from parts group by parts.dog_id $fn$; revoke execute on function public.my_dog_bowls() from public, anon; grant execute on function public.my_dog_bowls() to authenticated;

-- Me tab: marketing consent (off by default, timestamped when changed) and the list of teammates shown under the team.
alter table public.profiles add column if not exists marketing_opt_in boolean not null default false; alter table public.profiles add column if not exists marketing_opt_in_at timestamptz; grant update (marketing_opt_in) on public.profiles to authenticated; create or replace function public.stamp_marketing_consent() returns trigger language plpgsql security definer set search_path = public as $fn$ begin if new.marketing_opt_in is distinct from old.marketing_opt_in then new.marketing_opt_in_at := now(); end if; return new; end $fn$; revoke execute on function public.stamp_marketing_consent() from public, anon, authenticated; create or replace trigger marketing_consent before update of marketing_opt_in on public.profiles for each row execute function public.stamp_marketing_consent(); create or replace function public.team_mates() returns table (display_name text, is_captain boolean, is_me boolean) language sql stable security definer set search_path = public as $fn$ select p.display_name, (w.captain_id = p.user_id or (w.captain_id is null and w.created_by = p.user_id)), p.user_id = auth.uid() from public.profiles p join public.workplaces w on w.id = p.workplace_id where p.workplace_id = (select workplace_id from public.profiles where user_id = auth.uid()) order by 2 desc, 3 desc, 1 $fn$; revoke execute on function public.team_mates() from public, anon; grant execute on function public.team_mates() to authenticated;

-- Leaderboard: individual walkers (Pup) only appear if they opt in. Teams are Pack (up to 250 staff, includes the old Pup size), Big Dog, Top Dog.
alter table public.profiles add column if not exists show_on_leaderboard boolean not null default false; grant update (show_on_leaderboard) on public.profiles to authenticated; create or replace function public.walker_board() returns table (display_name text, steps bigint, bowls int, is_me boolean) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select p.user_id, p.display_name, coalesce(sum(s.steps), 0)::bigint as t from public.profiles p left join public.step_days s on s.user_id = p.user_id and s.day between (select starts_on from c) and (select ends_on from c) where p.show_on_leaderboard group by p.user_id, p.display_name) select ut.display_name, ut.t, public.milestone_count(ut.t), ut.user_id = auth.uid() from ut order by ut.t desc, ut.display_name limit 100 $fn$; revoke execute on function public.walker_board() from public, anon; grant execute on function public.walker_board() to authenticated;

-- Dogs can have several photos. photo_url is the small round picture; photos is the gallery on the dog's page. Files live in app/dogs/.
alter table public.dogs add column if not exists photos text[] not null default '{}';
insert into public.dogs (shelter_id, name, photo_url, photos, coat, ear, is_demo) select s.id, 'Lima', '/dogs/lima-thumb.jpg', array['/dogs/lima-1.jpg', '/dogs/lima-2.jpg'], '#F1E6D2', '#D9C3A0', true from public.shelters s where s.is_demo order by s.created_at limit 1;
